_sage_const_1 = Integer(1); _sage_const_0p0000001 = RealNumber('0.0000001'); _sage_const_0 = Integer(0); _sage_const_10000000 = Integer(10000000); _sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_0p000001 = RealNumber('0.000001'); _sage_const_20 = Integer(20); _sage_const_0p00000001 = RealNumber('0.00000001'); _sage_const_40 = Integer(40)# SDP solver using cutting plane method and LP solver
