import sys



field=Integer

def rescale_number(x, constants_rescale, kill_if_fail=True):
    """ Rescaling and testing that rescaling indeed gives an integer"""
    
    if constants_rescale == _sage_const_1 :
        return field(float(x))
    
    x_float = float(x)*constants_rescale
    x_rounded = round(x_float)
    if abs(x_float - x_rounded) > _sage_const_0p0000001 :
        print("Rescaling did not work for x=",x," result was",x_rounded,"which is not precise for",x_float)
        print("Try a different rescaling of the semidefinite program.")
        if kill_if_fail:
            sys.exit()
 
    return field(x_rounded)


################################################################################### UTILITIES
# Reads the whole problem as integer program
# the program has to be integral. This is a hack
# for SDP programs that were solved without scaled objective
# and are expensive to resolve
def read_problem_file(filename,constants_rescale=_sage_const_1 ,constraint_from=_sage_const_0 , constraint_to=_sage_const_10000000 ):
    f = open(filename, 'r')

    line = f.readline()
    line = line.strip()
    num_constraints = int(line)

    line = f.readline()
    line = line.strip()
    num_blocks = int(line)

    line = f.readline()
    parts = line.split()
    block_sizes = []
    for part in parts:
        block_sizes.append(int(part))

    line = f.readline()
    parts = line.split()

    constants = []
    used_constraints=_sage_const_0 

    for i in range(num_constraints):
        if i >= constraint_from and i < constraint_to:
            constants.append(rescale_number(parts[i], constants_rescale))
            used_constraints += _sage_const_1 
    """            
    if constants_rescale == 1:
        for i in xrange(num_constraints):
           if i >= constraint_from and i < constraint_to:
               constants.append(field(parts[i]))
               used_constraints += 1
    else:
        for i in xrange(num_constraints):
           if i >= constraint_from and i < constraint_to:
               constants.append(field(int(float(parts[i])*constants_rescale+0.5)))
               used_constraints += 1
    """

    # blocks that are integer numbers right away
    blocks = []
    for size in block_sizes:
        if size < _sage_const_0 :
            #block = [ matrix(ZZ,1,-size) for x in range(num_constraints+1) ]
            block = [ matrix(ZZ,_sage_const_1 ,-size) for x in range(used_constraints+_sage_const_1 ) ]
        else:
            block = [ matrix(ZZ,size,size, sparse=True) for x in range(used_constraints+_sage_const_1 ) ]
            #block = [ matrix(ZZ,size,size, sparse=True) for x in range(num_constraints+1) ]
            #block = [ matrix(QQ,size,size) for x in range(num_constraints+1) ]
        blocks.append(block)


    t_coef = [_sage_const_0 ]*num_constraints
    while True:
        line = f.readline()
        if len(line) == _sage_const_0 :
            break
        parts = line.split()
        if len(parts) == _sage_const_0 :
            continue
        constraint = int(parts[_sage_const_0 ])
        # Read also a bit arround to accommodate for mistakes..
        # Blocks are shifted by one
        #if constraint <= constraint_from or constraint > constraint_to:
        #    continue
        block_num = int(parts[_sage_const_1 ])
        row = int(parts[_sage_const_2 ])
        column = int(parts[_sage_const_3 ])
        value = rescale_number(parts[_sage_const_4 ], constants_rescale)
        '''
        if constants_rescale == 1:
            value = field(parts[4])
        else:
            value = field(float(parts[4])*constants_rescale)
        '''
        if block_sizes[block_num - _sage_const_1 ] < _sage_const_0 :
            blocks[block_num - _sage_const_1 ][constraint-constraint_from][_sage_const_0 , column - _sage_const_1 ] += value
            if (-block_sizes[block_num - _sage_const_1 ] == num_constraints+_sage_const_1  or  -block_sizes[block_num - _sage_const_1 ] == num_constraints+_sage_const_2 ) and -block_sizes[block_num - _sage_const_1 ] == column:
                t_coef[constraint-constraint_from-_sage_const_1 ] = abs(value)/constants_rescale
        else:
            blocks[block_num - _sage_const_1 ][constraint-constraint_from][row - _sage_const_1 , column - _sage_const_1 ] += value
            if row != column:
                blocks[block_num - _sage_const_1 ][constraint-constraint_from][column - _sage_const_1 , row - _sage_const_1 ] += value

    problem = dict()
    problem['num_constraints'] = used_constraints
    problem['num_blocks'] = num_blocks
    problem['block_sizes'] = block_sizes
    problem['blocks'] = blocks
    problem['constants'] = constants
    problem['constants_rescale'] = constants_rescale
    problem['t_coef'] = t_coef
    f.close()
    return problem


def rescale_vector(v):
    """ Rescale a vector of numbers by the constants_rescale factor"""
    nonzeros = [x for x in v if abs(x) > _sage_const_0p000001 ]
    if len(nonzeros) == _sage_const_0 :
        return [_sage_const_0 ]*len(v)
    min_nonzero = min(nonzeros)
    
    return [x/min_nonzero for x in v ]

def solve_using_LP(problem, it=_sage_const_20 , verbose=False):

    num_blocks = problem['num_blocks']
    block_sizes = problem['block_sizes']
    blocks = problem['blocks']
    constants = problem['constants']
    num_constraints = problem['num_constraints']
    constants_rescale = problem['constants_rescale']
    t_coef = problem['t_coef']

    #d = MixedIntegerLinearProgram(maximization=True)
    d = MixedIntegerLinearProgram(maximization=False)
    y = d.new_variable(real=True, nonnegative=True)  # will be used as an array of length constants 

    yrange = range(num_constraints)

    ## TODO change the -c to the objective 
    #print("Objective:",[ -c*y[i]  for i,c in enumerate(constants) ])

    #d.set_objective( sum([ -c*y[i]  for i,c in enumerate(constants) ]) )
    d.set_objective( sum([ c*y[i]  for i,c in enumerate(constants) ]) )

    #print('t_coef=',t_coef)
    d.add_constraint(sum([ t_coef[i]*y[i]  for i in yrange ])  == _sage_const_1 )

    
    # Add linear constraints 
    for blockID,blocksize in enumerate(block_sizes):
        if blocksize < _sage_const_0  and (-blocksize != num_constraints+_sage_const_1 ) and  (-blocksize != num_constraints+_sage_const_2 ):
            for constraintID in range(-blocksize):
                #print("blocksize=",blocksize,"blockID=",blockID,"constraintID=",constraintID,"num_blocks=",num_blocks)
                #print([i for i in yrange])
                #print(blocks[blockID])
                #d.add_constraint(sum([ blocks[blockID][i][constraintID,0]*y[i] for i in yrange if blocks[blockID][i][constraintID,0] != 0 ])  >= 0)
                d.add_constraint(sum([ blocks[blockID][i+_sage_const_1 ][_sage_const_0 ,constraintID]*y[i] for i in yrange if blocks[blockID][i+_sage_const_1 ][_sage_const_0 ,constraintID] != _sage_const_0  ])  >= _sage_const_0 )
    

    dconstraints = _sage_const_1  

    for test_run in range(it):

        print("Iter:",test_run+_sage_const_1 ,end=" ")
        print("Upper bound is",d.solve()/constants_rescale," with ",dconstraints," constraints")

        yval=[ d.get_values(y[i]) for i in  yrange ]

        if verbose:
            print("  yval=",yval)


        # This should run in parallel
        for blockID in range(num_blocks):
            if block_sizes[blockID] <= _sage_const_0 :
                continue

            A=blocks[blockID][_sage_const_0 ] # just zero matrix of the right size

            for i,yvali in enumerate(yval):
                A += yvali*blocks[blockID][i+_sage_const_1 ]

            A = matrix(RDF, A,sparse=False)

            if verbose:
                print("Matrix A"+str(blockID+_sage_const_1 ),"=")
                print(A)

            evs = A.eigenvectors_right()
            #print("Got eigenvectors",evs)

            # Find smallest eigenvalue
            minID = _sage_const_0 
            minval = evs[_sage_const_0 ][_sage_const_0 ]
            for i in range(_sage_const_1 , len(evs)):
                if evs[i][_sage_const_0 ] < minval:
                    minID = i
                    minval = evs[i][_sage_const_0 ]

            # Smallest eigenvalue
            e = evs[minID]

            if verbose:
                print(" lambda=",e[_sage_const_0 ]," with eigenvector",e[_sage_const_1 ][_sage_const_0 ])

            #for e in evs:

            if e[_sage_const_0 ] < -_sage_const_0p00000001 :
                #print("  Eigenvalue",e[0],"with eigenvector",e[1][0])
                v = e[_sage_const_1 ][_sage_const_0 ]

                #
                v = vector(rescale_vector(v))
                if verbose:
                    print("  Rescaled eigenvector",v)

                #print("  v=",v)

                # Test if the new constraint violates the current solution
                c = [ v*blocks[blockID][i+_sage_const_1 ]*v for i in yrange ]  

                #print("c=",c)
                #print("yval=",yval,"yrange=",yrange)

                #print("presum=",[ c[i]*yval[i] for i in yrange])

                # Test if we have an interesting constraint
                new_contraint = sum([ real_part(c[i])*yval[i] for i in yrange])

                #print("Sum=",new_contraint)

                if new_contraint < _sage_const_0 :
                    #print("  Found new constraint",c)
                    # This is somewhat a critical section of the code.
                    d.add_constraint(sum([  real_part(c[i])*y[i]  for i in yrange ])  >= _sage_const_0 )
                    dconstraints += _sage_const_1 
                    if verbose:
                        for i in yrange:
                            print( str(real_part(c[i]))+"*y_"+str(i+_sage_const_1 ),end=" ")
                        print(" >= 0")
            
        if verbose:
            print()


def solve_dats_using_LP(datsfile, scale, iterations=_sage_const_40 , verbose=False):
    p = read_problem_file(datsfile, scale)
    solve_using_LP(p, iterations, verbose)


